SELECT data_rows.message_id, data_rows.should_delete, data_rows.response_overflow, data_rows.turn_id, data_rows.op_id, data_rows.attempt, data_rows.tool_name, data_rows.tool_kind, data_rows.status, data_rows.request_hash, data_rows.error_code, data_rows.error_message, data_rows.retriable, data_rows.started_at, data_rows.completed_at, data_rows.latency_ms, data_rows.cost, data_rows.trace_id, data_rows.span_id, data_rows.request_payload_id, data_rows.response_payload_id, data_rows.run_id, data_rows.iteration FROM  (SELECT 0 AS should_delete, 0 AS response_overflow, `message_id`, `turn_id`, `op_id`, `attempt`, `tool_name`, `tool_kind`, `status`, `request_hash`, `error_code`, `error_message`, `retriable`, `started_at`, `completed_at`, `latency_ms`, `cost`, `trace_id`, `span_id`, `request_payload_id`, `response_payload_id`, `run_id`, `iteration` FROM tool_call)  data_rows